const app = document.querySelector("#app");
const tokenKey = "yv_access_token";
let memoryToken = "";
// Storage can be disabled by browser privacy settings or file previews. Navigation must still work without it.
const getToken = () => { try { return sessionStorage.getItem(tokenKey) || memoryToken; } catch { return memoryToken; } };
const saveToken = token => { memoryToken = token || ""; try { sessionStorage.setItem(tokenKey, memoryToken); } catch { /* memory-only session */ } };
const clearToken = () => { memoryToken = ""; try { sessionStorage.removeItem(tokenKey); } catch { /* memory-only session */ } };
const esc = (value = "") => String(value).replace(/[&<>'"]/g, c => ({ "&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':"&quot;" }[c]));
const money = value => `₹${Number(value || 0).toLocaleString("en-IN")}`;
const split = value => value.split(",").map(x => x.trim()).filter(Boolean);
async function api(path, options = {}) { const headers = { ...(options.body ? { "Content-Type":"application/json" } : {}), ...(getToken() ? { Authorization:`Bearer ${getToken()}` } : {}), ...options.headers }; const response = await fetch(`/api${path}`, { ...options, headers }); const data = await response.json().catch(() => ({})); if (!response.ok) throw new Error(data.error?.message || "Unable to complete that request."); return data; }
function setAccountLink() { const link = document.querySelector("#account-link"); link.href = getToken() ? "#/account" : "#/auth"; link.textContent = getToken() ? "My account" : "Sign in"; }
let activeMessageStream = null;
function render(html) { if (activeMessageStream) { activeMessageStream.close(); activeMessageStream = null; } app.innerHTML = html; window.scrollTo({ top: 0, behavior: "auto" }); const trafficMap = app.querySelector(".live-traffic-map"); if (trafficMap) setTimeout(() => mountLiveTrafficMap(trafficMap), 0); }
function message(text, kind = "") { return text ? `<p class="notice ${kind}">${esc(text)}</p>` : ""; }

async function home() { render(`<section class="hero"><div class="inside"><div><span class="eyebrow">THE INTELLIGENT WAY TO SEE INDIA</span><h1>A journey is better when it feels <i>known.</i></h1><p>Local knowledge, destination context, and date-aware travel signals in one considered way to plan deeper journeys.</p><form class="search" id="home-search"><input name="q" placeholder="Where would you like to go?" aria-label="Destination search"><button>Discover places →</button></form></div><div class="poster"><div><span class="eyebrow">YATRA SIGNAL</span><b>Go farther<br>in perspective.</b></div></div></div></section><section class="wrap"><span class="eyebrow">THREE SIGNALS. ONE JOURNEY.</span><h1>Travel with more than a map.</h1><div class="features"><article class="card"><span class="eyebrow">01 · FIND</span><h3>Local guides</h3><p>Browse verified people and the experiences they choose to offer.</p></article><article class="card"><span class="eyebrow">02 · CHECK</span><h3>Forecast & hazards</h3><p>See the weather for your selected travel date and weather-derived cautions.</p></article><article class="card"><span class="eyebrow">03 · PLAN</span><h3>Route context</h3><p>Keep traffic and route-diversion status beside the itinerary.</p></article></div></section>`); document.querySelector("#home-search").onsubmit = e => { e.preventDefault(); location.hash = `#/destinations?q=${encodeURIComponent(new FormData(e.target).get("q"))}`; }; }

async function destinations() { render(`<section class="wrap"><div class="page-head"><div><span class="eyebrow">EXPLORE INDIA</span><h1>Destinations</h1></div><form class="search" id="destination-search"><input name="q" placeholder="Search destination or state"><button>Search</button></form></div><div id="destination-list" class="grid three"><p class="spinner">Finding places…</p></div></section>`); const query = new URLSearchParams(location.hash.split("?")[1] || "").get("q") || ""; document.querySelector("#destination-search input").value = query; document.querySelector("#destination-search").onsubmit = e => { e.preventDefault(); location.hash = `#/destinations?q=${encodeURIComponent(new FormData(e.target).get("q"))}`; }; try { const { data } = await api(`/destinations${query ? `?q=${encodeURIComponent(query)}` : ""}`); document.querySelector("#destination-list").innerHTML = data.length ? data.map(d => `<a class="destination-card" href="#/planner?destination=${d._id}"><span class="eyebrow">${esc(d.state || "INDIA")}</span><h2>${esc(d.name)}</h2><p>${esc(d.summary || "Plan your journey with local context.")}</p></a>`).join("") : `<div class="empty">No published destinations match that search.</div>`; } catch (e) { document.querySelector("#destination-list").innerHTML = `<div class="notice error">${esc(e.message)}</div>`; } }

async function guides() { render(`<section class="wrap"><div class="page-head"><div><span class="eyebrow">LOCAL GUIDE MARKETPLACE</span><h1>Meet India through its people.</h1><p>Verified local guides and their independently designed experiences.</p></div><a class="button secondary" href="#/auth">Become a guide</a></div><div id="guide-list" class="grid three"><p class="spinner">Loading guides…</p></div></section>`); try { const { data } = await api("/guides"); document.querySelector("#guide-list").innerHTML = data.length ? data.map(g => `<article class="card guide-card"><span class="eyebrow">VERIFIED LOCAL GUIDE</span><h2>${esc(g.userId?.name || "Local guide")}</h2><p>${esc(g.bio || "Local expertise tailored to your journey.")}</p><div class="tags">${(g.languages || []).map(x => `<span class="tag">${esc(x)}</span>`).join("")}</div><span class="price">${money(g.pricePerDay)} / day</span><p><b>★ ${Number(g.rating?.average || 0).toFixed(1)}</b> from ${g.rating?.count || 0} traveler review${g.rating?.count === 1 ? "" : "s"}</p>${g.packages?.length ? `<p><b>Experiences:</b> ${esc(g.packages.filter(p => p.active).map(p => p.title).join(", "))}</p>` : ""}<a class="button secondary" href="#/request?guide=${g._id}">Request this guide →</a></article>`).join("") : `<div class="empty">No guides are public yet. Guide profiles appear here after review.</div>`; } catch (e) { document.querySelector("#guide-list").innerHTML = `<div class="notice error">${esc(e.message)}</div>`; } }

async function planner() { render(`<section class="wrap"><div class="page-head"><div><span class="eyebrow">DATE-AWARE TRAVEL INTELLIGENCE</span><h1>Plan with context.</h1><p>Select a destination and your travel date for a live forecast, weather hazards, traffic status, and diversion-feed status.</p></div></div><section class="panel"><form id="advisory-form" class="form-grid"><label>Destination<select name="destination" required><option value="">Loading destinations…</option></select></label><label>Travel date<input name="date" type="date" required></label><div><button>Check travel conditions</button></div></form><div class="notice">Ready to travel with a local expert? <button type="button" class="button secondary" id="send-guide-request">Send request to a local guide →</button></div></section><section id="advisory-result" class="panel hidden"></section><p class="notice">Forecast data is sourced from Open-Meteo when available. Traffic and diversion notices are deliberately labelled unavailable until a verified live provider is connected—never treated as a real-time claim.</p></section>`); const date = new Date(); date.setDate(date.getDate() + 1); const dateInput = document.querySelector('[name="date"]'); dateInput.value = date.toISOString().slice(0,10); dateInput.min = new Date().toISOString().slice(0,10); try { const { data } = await api("/destinations"); const select = document.querySelector('[name="destination"]'); select.innerHTML = `<option value="">Choose a destination</option>${data.map(d => `<option value="${d._id}">${esc(d.name)} · ${esc(d.state)}</option>`).join("")}`; const preferred = new URLSearchParams(location.hash.split("?")[1] || "").get("destination"); if (preferred) select.value = preferred; } catch (e) { document.querySelector("#advisory-form").insertAdjacentHTML("afterend", message(e.message,"error")); }
 document.querySelector("#send-guide-request").onclick = () => { const destination = document.querySelector('[name="destination"]').value; location.hash = `#/request${destination ? `?destination=${destination}` : ""}`; }; document.querySelector("#advisory-form").onsubmit = async e => { e.preventDefault(); const form = new FormData(e.target); const output = document.querySelector("#advisory-result"); output.classList.remove("hidden"); output.innerHTML = `<p class="spinner">Checking conditions for your selected date…</p>`; try { const { data } = await api(`/travel-advisory/${form.get("destination")}?date=${form.get("date")}`); const temp = data.weather.temperature ? `${data.weather.temperature.min}–${data.weather.temperature.max}${data.weather.temperature.unit}` : "—"; const rain = data.weather.precipitation ? `${data.weather.precipitation.chance}% chance · ${data.weather.precipitation.amount}${data.weather.precipitation.unit}` : "—"; output.innerHTML = `<span class="eyebrow">${esc(data.destination)} · ${esc(data.date)}</span><h2>Your travel outlook</h2><div class="advisory"><article class="metric"><span class="status ${data.weather.status}">${esc(data.weather.status)}</span><h3>${esc(data.weather.summary)}</h3><p><b>${temp}</b><br>${rain}<br><small>Source: ${esc(data.weather.source || "—")}</small></p></article><article class="metric"><span class="status ${data.traffic.status}">${esc(data.traffic.status)}</span><h3>Traffic</h3><p>${esc(data.traffic.summary)}</p></article><article class="metric"><span class="status ${data.route.status}">${esc(data.route.status)}</span><h3>Route diversions</h3><p>${esc(data.route.summary)}</p></article></div><h3>Hazards and planning notes</h3><div>${data.hazards.map(h => `<div class="hazard"><b>${esc(h.title)} <span class="tag">${esc(h.level)}</span></b>${esc(h.detail)}</div>`).join("")}</div>`; } catch (error) { output.innerHTML = message(error.message,"error"); } }; }

async function tripRequest() {
  if (!getToken()) return location.hash = "#/auth";
  render(`<section class="wrap"><div class="page-head"><div><span class="eyebrow">TRIP REQUEST</span><h1>Send a request to your local guide.</h1><p>Your guide will see your dates and details, then approve or decline from their own portal.</p></div></div><section class="panel"><form id="request-form"><div class="form-grid"><label>Local guide<select name="guideId" required><option value="">Loading guides…</option></select></label><label>Destination<select name="destinationId" required><option value="">Loading destinations…</option></select></label><label>Trip starts<input name="startsAt" type="date" required></label><label>Trip ends<input name="endsAt" type="date" required></label><label>Guests<input name="guests" type="number" min="1" max="20" value="1" required></label></div><label>Message for your guide<textarea name="note" rows="4" maxlength="1000" placeholder="Tell the guide what you want from the trip."></textarea></label><button>Send request to guide</button><div id="request-message"></div></form></section></section>`);
  const today = new Date().toISOString().slice(0, 10); document.querySelector('[name="startsAt"]').min = today; document.querySelector('[name="endsAt"]').min = today;
  try { const [{ data: guides }, { data: destinations }] = await Promise.all([api("/guides"), api("/destinations")]); const guideSelect = document.querySelector('[name="guideId"]'); guideSelect.innerHTML = `<option value="">Choose a verified guide</option>${guides.map(guide => `<option value="${guide._id}">${esc(guide.userId?.name || "Local guide")} · ${money(guide.pricePerDay)}/day</option>`).join("")}`; const destinationSelect = document.querySelector('[name="destinationId"]'); destinationSelect.innerHTML = `<option value="">Choose a destination</option>${destinations.map(destination => `<option value="${destination._id}">${esc(destination.name)} · ${esc(destination.state)}</option>`).join("")}`; const selectedGuide = new URLSearchParams(location.hash.split("?")[1] || "").get("guide"); if (selectedGuide) guideSelect.value = selectedGuide; } catch (error) { document.querySelector("#request-message").innerHTML = message(error.message, "error"); }
  const selectedDestination = new URLSearchParams(location.hash.split("?")[1] || "").get("destination"); if (selectedDestination) document.querySelector('[name="destinationId"]').value = selectedDestination;
  document.querySelector("#request-form").onsubmit = async event => { event.preventDefault(); const form = Object.fromEntries(new FormData(event.target)); const out = document.querySelector("#request-message"); try { await api("/bookings", { method: "POST", body: JSON.stringify({ ...form, startsAt: new Date(`${form.startsAt}T09:00:00`).toISOString(), endsAt: new Date(`${form.endsAt}T18:00:00`).toISOString(), guests: Number(form.guests) }) }); out.innerHTML = message("Request sent. Your guide’s decision will appear in My account.", "success"); event.target.reset(); } catch (error) { out.innerHTML = message(error.message, "error"); } };
}

async function auth() { if (getToken()) return account(); render(`<section class="wrap"><div class="panel" style="max-width:480px;margin:auto"><span class="eyebrow">YATRA VERSE</span><h1 id="auth-title">Welcome back.</h1><form id="auth-form"><div id="register-fields" class="hidden"><label>Name<input name="name" minlength="2"></label><label>I’m joining as<select name="role"><option value="traveler">Traveler</option><option value="guide">Local guide</option></select></label></div><label>Email<input name="email" type="email" required></label><label>Password<input name="password" type="password" minlength="8" required></label><button id="auth-submit">Sign in</button></form><p id="auth-message"></p><button class="button secondary" id="mode-toggle">Need an account? Register</button></div></section>`); let mode = "login"; document.querySelector("#mode-toggle").onclick = () => { mode = mode === "login" ? "register" : "login"; document.querySelector("#register-fields").classList.toggle("hidden", mode === "login"); document.querySelector("#auth-title").textContent = mode === "login" ? "Welcome back." : "Begin your journey."; document.querySelector("#auth-submit").textContent = mode === "login" ? "Sign in" : "Create account"; document.querySelector("#mode-toggle").textContent = mode === "login" ? "Need an account? Register" : "Already have an account? Sign in"; }; document.querySelector("#auth-form").onsubmit = async e => { e.preventDefault(); const out = document.querySelector("#auth-message"); try { const form = Object.fromEntries(new FormData(e.target)); const result = await api(`/auth/${mode}`, { method:"POST", body:JSON.stringify(form) }); saveToken(result.data.accessToken); setAccountLink(); location.hash = result.data.user.roles.includes("guide") ? "#/guide" : "#/account"; } catch (error) { out.innerHTML = message(error.message,"error"); } }; }

async function account() { render(`<section class="wrap"><div id="account-content" class="spinner">Preparing your travel space…</div></section>`); try { const [{ data: me }, { data: bookings }] = await Promise.all([api("/auth/me"), api("/bookings/mine")]); const user = me.user; document.querySelector("#account-content").innerHTML = `<div class="page-head"><div><span class="eyebrow">YOUR TRAVEL SPACE</span><h1>Welcome, ${esc(user.name)}.</h1></div><button id="signout" class="button secondary">Sign out</button></div><div class="two-col"><section class="panel"><span class="eyebrow">YOUR BOOKINGS</span><h2>Upcoming journeys</h2>${bookings.length ? `<div class="list">${bookings.map(b => `<article class="item"><div class="item-header"><b>${esc(b.destinationId?.name || "Destination")}</b><span class="tag">${esc(b.status.replace("_"," "))}</span></div><p>${new Date(b.startsAt).toLocaleDateString()} · ${b.guests} guest(s) · ${esc(b.guideId?.userId?.name || "Guide")}</p></article>`).join("")}</div>` : `<div class="empty">Your next story is still waiting. <a href="#/guides">Find a guide →</a></div>`}</section><aside class="panel"><span class="eyebrow">ACCOUNT</span><h2>Your profile</h2><p>${esc(user.email)}</p><p>Membership: ${esc(user.roles.join(" · "))}</p>${user.roles.includes("guide") ? `<a class="button" href="#/guide">Open guide portal →</a>` : `<a class="button" href="#/planner">Plan a trip →</a>`}</aside></div>`; document.querySelector("#signout").onclick = () => { clearToken(); setAccountLink(); location.hash = "#/"; }; } catch (e) { clearToken(); setAccountLink(); location.hash = "#/auth"; } }

async function account() {
  render(`<section class="wrap"><div id="account-content" class="spinner">Preparing your travel space…</div></section>`);
  try {
    const [{ data: me }, { data: bookings }] = await Promise.all([api("/auth/me"), api("/bookings/mine")]); const user = me.user;
    const bookingHTML = bookings.length ? bookings.map(b => `<article class="item"><div class="item-header"><b>${esc(b.destinationId?.name || "Destination")}</b><span class="tag">${esc(b.status.replace("_", " "))}</span></div><p>${new Date(b.startsAt).toLocaleDateString()} · ${b.guests} guest(s) · ${esc(b.guideId?.userId?.name || "Guide")}</p>${b.status === "completed" ? `<button class="button secondary leave-review" data-booking="${b._id}" data-guide="${esc(b.guideId?.userId?.name || "your guide")}">Leave a review</button>` : ""}<div class="review-slot" id="review-${b._id}"></div></article>`).join("") : `<div class="empty">Your next story is still waiting. <a href="#/guides">Find a guide →</a></div>`;
    document.querySelector("#account-content").innerHTML = `<div class="page-head"><div><span class="eyebrow">YOUR TRAVEL SPACE</span><h1>Welcome, ${esc(user.name)}.</h1></div><button id="signout" class="button secondary">Sign out</button></div><div class="two-col"><section class="panel"><span class="eyebrow">YOUR BOOKINGS</span><h2>Journeys and reviews</h2><div class="list">${bookingHTML}</div></section><aside class="panel"><span class="eyebrow">ACCOUNT</span><h2>Your profile</h2><p>${esc(user.email)}</p><p>Membership: ${esc(user.roles.join(" · "))}</p>${user.roles.includes("guide") ? `<a class="button" href="#/guide">Open guide portal →</a>` : `<a class="button" href="#/planner">Plan a trip →</a>`}${user.roles.includes("admin") ? `<p><a class="button secondary" href="#/admin">Open admin portal →</a></p>` : ""}</aside></div>`;
    document.querySelector("#signout").onclick = () => { clearToken(); setAccountLink(); location.hash = "#/"; };
    document.querySelectorAll(".leave-review").forEach(button => button.onclick = () => { const slot = document.querySelector(`#review-${button.dataset.booking}`); slot.innerHTML = `<form class="review-form"><label>How was your trip with ${esc(button.dataset.guide)}?<select name="rating"><option value="5">5 — Excellent</option><option value="4">4 — Very good</option><option value="3">3 — Good</option><option value="2">2 — Needs improvement</option><option value="1">1 — Poor</option></select></label><label>Share your experience<textarea name="comment" rows="3" maxlength="1200" placeholder="Your honest review helps future travelers."></textarea></label><button>Publish review</button></form>`; slot.querySelector("form").onsubmit = async event => { event.preventDefault(); try { const form = new FormData(event.target); await api("/reviews", { method: "POST", body: JSON.stringify({ bookingId: button.dataset.booking, rating: Number(form.get("rating")), comment: form.get("comment") }) }); slot.innerHTML = message("Thanks — your review is now part of this guide’s rating.", "success"); button.remove(); } catch (error) { slot.innerHTML = message(error.message, "error"); } }; });
  } catch { clearToken(); setAccountLink(); location.hash = "#/auth"; }
}

async function adminPortal() {
  if (!getToken()) return location.hash = "#/auth";
  render(`<section class="wrap"><div id="admin-content" class="spinner">Loading the moderation workspace…</div></section>`);
  try {
    const [{ data: me }, { data: guides }, { data: bookings }, { data: reviews }] = await Promise.all([api("/auth/me"), api("/admin/guides"), api("/admin/bookings"), api("/admin/reviews")]);
    if (!me.user.roles.includes("admin")) return location.hash = "#/account";
    document.querySelector("#admin-content").innerHTML = `<div class="page-head"><div><span class="eyebrow">OWNER & MODERATION PORTAL</span><h1>Keep the marketplace trustworthy.</h1><p>Approve completed guide profiles before they are visible to travelers, and remove profiles when reviews or conduct require it.</p></div><a class="button secondary" href="#/account">Back to account</a></div><section class="panel"><span class="eyebrow">GUIDE APPROVALS</span><h2>Guide profiles</h2><div class="list">${guides.length ? guides.map(g => `<article class="item"><div class="item-header"><div><b>${esc(g.userId?.name || "Guide")}</b><p>${esc(g.userId?.email || "")} · ${esc(g.residenceState || "No base set")}</p><p>${esc(g.bio || "No profile description yet.")}</p></div><span class="tag">${esc(g.verificationStatus)}</span></div><p>₹${Number(g.pricePerDay || 0).toLocaleString("en-IN")} / day · ★ ${Number(g.rating?.average || 0).toFixed(1)} (${g.rating?.count || 0} reviews)</p><div class="tags"><button class="approve-guide" data-id="${g._id}">Approve & publish</button><button class="button secondary reject-guide" data-id="${g._id}">Reject / hide</button><button class="button danger delete-guide" data-id="${g._id}">Remove from database</button></div></article>`).join("") : `<div class="empty">No guide profiles yet.</div>`}</div></section><section class="panel" style="margin-top:28px"><span class="eyebrow">TRIP COMPLETION</span><h2>Enable honest traveler reviews</h2><p>Mark a trip completed only after it has genuinely finished. The traveler will then see the review form in their account.</p><div class="list">${bookings.length ? bookings.map(b => `<article class="item"><div class="item-header"><b>${esc(b.destinationId?.name || "Destination")} · ${esc(b.guideId?.userId?.name || "Guide")}</b><span class="tag">${esc(b.status)}</span></div><p>${esc(b.travelerId?.name || "Traveler")} · ${new Date(b.startsAt).toLocaleDateString()}</p>${b.status !== "completed" ? `<button class="complete-booking" data-id="${b._id}">Mark trip completed</button>` : `<p class="notice success">Completed — traveler can review.</p>`}</article>`).join("") : `<div class="empty">No bookings yet.</div>`}</div></section>`;
    document.querySelector("#admin-content").insertAdjacentHTML("beforeend", `<section class="panel" style="margin-top:28px"><span class="eyebrow">TRAVELER FEEDBACK</span><h2>Recent reviews</h2><div class="list">${reviews.length ? reviews.map(review => `<article class="item"><b>${esc(review.guideId?.userId?.name || "Guide")} · ${review.rating}/5</b><p>${esc(review.travelerId?.name || "Traveler")}</p><p>${esc(review.comment || "No written comment")}</p></article>`).join("") : `<div class="empty">No completed-trip reviews yet.</div>`}</div></section>`);
    document.querySelectorAll(".approve-guide").forEach(b => b.onclick = () => updateGuide(b.dataset.id, "approved")); document.querySelectorAll(".reject-guide").forEach(b => b.onclick = () => updateGuide(b.dataset.id, "rejected")); document.querySelectorAll(".delete-guide").forEach(b => b.onclick = async () => { if (!confirm("Remove this guide profile and its reviews permanently?")) return; try { await api(`/admin/guides/${b.dataset.id}`, { method: "DELETE" }); adminPortal(); } catch (error) { alert(error.message); } }); document.querySelectorAll(".complete-booking").forEach(b => b.onclick = async () => { try { await api(`/admin/bookings/${b.dataset.id}/complete`, { method: "PATCH" }); adminPortal(); } catch (error) { alert(error.message); } });
  } catch (error) { render(`<section class="wrap">${message(error.message, "error")}</section>`); }
}
async function updateGuide(id, status) { try { await api(`/admin/guides/${id}`, { method: "PATCH", body: JSON.stringify({ status }) }); adminPortal(); } catch (error) { alert(error.message); } }

function contact() { render(`<section class="wrap"><div class="two-col"><section><span class="eyebrow">CONTACT YATRA VERSE</span><h1>Every good journey starts with someone who listens.</h1><p style="font-size:18px;color:var(--muted)">Whether you are choosing a guide, planning a special trip, or simply need a little clarity before you book, we are here to help you spend confidently and travel meaningfully.</p><p style="font-size:18px;color:var(--muted)">Your time and money matter. We will do our best to make each recommendation clear, useful, and worth the journey.</p></section><aside class="panel"><span class="eyebrow">WE’D LOVE TO HELP</span><h2>Talk to Shivam</h2><p><b>Shivam Pandey</b><br>Website owner & travel support</p><p><b>Email</b><br><a href="mailto:pandeysp8080@gmail.com">pandeysp8080@gmail.com</a></p><p><b>Call</b><br><a href="tel:+917081127881">+91 7081127881</a></p><p class="notice">Reach out with your question and we’ll help you make the most of your travel budget, not just make another booking.</p></aside></div></section>`); }

const blankProfile = () => ({ bio:"", residenceState:"", serviceStates:[], languages:[], specialties:[], destinationIds:[], pricePerDay:"", packages:[], tripOfferings:[], availabilityNote:"", contactPhone:"", contactEmail:"", verificationStatus:"not_started" });
async function guidePortal() { if (!getToken()) return location.hash = "#/auth"; render(`<section class="wrap"><div id="guide-content" class="spinner">Preparing your guide portal…</div></section>`); try { const [{ data: me }, profileResult, destinationResult] = await Promise.all([api("/auth/me"),api("/guides/me/profile"),api("/destinations")]); if (!me.user.roles.includes("guide")) return location.hash = "#/account"; let profile = profileResult.data || blankProfile(), destinations = destinationResult.data; profile.destinationIds = (profile.destinationIds || []).map(d => typeof d === "string" ? d : d._id); drawGuide(); function drawGuide(note = "", kind = "") { document.querySelector("#guide-content").innerHTML = `<div class="page-head"><div><span class="eyebrow">LOCAL GUIDE PORTAL</span><h1>Build your local offering.</h1><p>You decide your daily price, experiences, and the exact things travelers receive on a trip.</p></div><a class="button secondary" href="#/account">Back to account</a></div>${message(note,kind)}<div class="notice">Review status: <b>${esc(profile.verificationStatus.replace("_"," "))}</b> ${["not_started","rejected"].includes(profile.verificationStatus) ? `<button id="submit-review" class="button small">Submit for verification</button>` : ""}</div><form id="guide-form"><div class="two-col"><section class="panel"><span class="eyebrow">YOUR EXPERTISE</span><h2>Profile and pricing</h2><label>About you<textarea name="bio" rows="4" placeholder="Tell travelers what you know best.">${esc(profile.bio)}</textarea></label><div class="form-grid"><label>State of residence<input name="residenceState" value="${esc(profile.residenceState)}"></label><label>Price per day (₹)<input name="pricePerDay" type="number" min="0" value="${esc(profile.pricePerDay)}"></label></div><label>States you serve <small>(comma-separated)</small><input name="serviceStates" value="${esc(profile.serviceStates.join(", "))}"></label><label>Languages <small>(comma-separated)</small><input name="languages" value="${esc(profile.languages.join(", "))}"></label><label>Specialties <small>(comma-separated)</small><input name="specialties" value="${esc(profile.specialties.join(", "))}"></label><label>Availability note<textarea name="availabilityNote" rows="2" placeholder="e.g. Available Friday to Monday; book 48 hours ahead.">${esc(profile.availabilityNote)}</textarea></label></section><section class="panel"><span class="eyebrow">SERVICE AREAS</span><h2>Destinations you cover</h2><div class="list">${destinations.map(d => `<label class="item"><input class="destination-choice" type="checkbox" value="${d._id}" ${profile.destinationIds.includes(d._id) ? "checked" : ""}> ${esc(d.name)} <small>· ${esc(d.state)}</small></label>`).join("") || "No destinations have been published yet."}</div></section></div><section class="panel" style="margin-top:28px"><div class="item-header"><div><span class="eyebrow">TRIP OFFERINGS</span><h2>What can travelers get with you?</h2><p>Make this fully yours: transport, meals, permits, photography, accessibility support, or anything else.</p></div><button class="button secondary" id="add-offering" type="button">Add offering</button></div><div id="offerings" class="list">${profile.tripOfferings.map(offeringHTML).join("") || `<div class="empty">Add the individual things you can offer on a trip.</div>`}</div></section><section class="panel" style="margin-top:28px"><div class="item-header"><div><span class="eyebrow">BOOKABLE EXPERIENCES</span><h2>Your packages</h2></div><button class="button secondary" id="add-package" type="button">Add package</button></div><div id="packages" class="list">${profile.packages.map(packageHTML).join("") || `<div class="empty">No packages yet. Add an experience travelers can book.</div>`}</div></section><p><button>Save guide profile</button></p></form>`; bindGuide(); }
 function offeringHTML(o={}) { return `<div class="item package offering"><div class="offer-row"><label>Name<input data-field="name" value="${esc(o.name)}" placeholder="Airport pickup"></label><label>Description<input data-field="description" value="${esc(o.description)}" placeholder="Private pickup from your arrival point"></label><label>Included<br><input data-field="included" type="checkbox" ${o.included ? "checked" : ""}></label><label>Extra cost ₹<input data-field="extraCost" type="number" min="0" value="${esc(o.extraCost || 0)}"></label><button type="button" class="button danger remove-offering">Remove</button></div></div>`; }
 function packageHTML(p={ title:"",durationHours:8,price:0,inclusions:[],exclusions:[],offeredItems:[],active:true }) { return `<article class="item package experience"><div class="item-header"><b>Experience</b><button type="button" class="button danger remove-package">Remove</button></div><div class="form-grid"><label>Package name<input data-field="title" value="${esc(p.title)}" placeholder="Old city food walk"></label><label>Duration (hours)<input data-field="durationHours" type="number" min="1" value="${p.durationHours}"></label><label>Price (₹)<input data-field="price" type="number" min="0" value="${p.price}"></label><label>Things offered in this package <small>(comma-separated)</small><input data-field="offeredItems" value="${esc((p.offeredItems || []).join(", "))}" placeholder="Tastings, local transport"></label><label>Included <small>(comma-separated)</small><input data-field="inclusions" value="${esc((p.inclusions || []).join(", "))}"></label><label>Not included <small>(comma-separated)</small><input data-field="exclusions" value="${esc((p.exclusions || []).join(", "))}"></label></div><label><input data-field="active" type="checkbox" ${p.active !== false ? "checked" : ""}> Available to book</label></article>`; }
 function bindGuide() { document.querySelector("#add-offering").onclick = () => { const list=document.querySelector("#offerings"); if (list.querySelector(".empty")) list.innerHTML=""; list.insertAdjacentHTML("beforeend",offeringHTML()); bindGuide(); }; document.querySelector("#add-package").onclick = () => { const list=document.querySelector("#packages"); if (list.querySelector(".empty")) list.innerHTML=""; list.insertAdjacentHTML("beforeend",packageHTML()); bindGuide(); }; document.querySelectorAll(".remove-offering").forEach(b => b.onclick=()=>b.closest(".offering").remove()); document.querySelectorAll(".remove-package").forEach(b => b.onclick=()=>b.closest(".experience").remove()); const review=document.querySelector("#submit-review"); if(review) review.onclick=async()=>{try{const r=await api("/guides/me/submit",{method:"POST"});profile.verificationStatus=r.data.verificationStatus;drawGuide("Profile submitted for verification.","success")}catch(e){drawGuide(e.message,"error")}}; document.querySelector("#guide-form").onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target); profile={...profile,bio:f.get("bio"),residenceState:f.get("residenceState"),serviceStates:split(f.get("serviceStates")),languages:split(f.get("languages")),specialties:split(f.get("specialties")),pricePerDay:f.get("pricePerDay"),availabilityNote:f.get("availabilityNote"),destinationIds:[...document.querySelectorAll(".destination-choice:checked")].map(x=>x.value),tripOfferings:[...document.querySelectorAll(".offering")].map(x=>({name:x.querySelector('[data-field="name"]').value,description:x.querySelector('[data-field="description"]').value,included:x.querySelector('[data-field="included"]').checked,extraCost:Number(x.querySelector('[data-field="extraCost"]').value)})),packages:[...document.querySelectorAll(".experience")].map(x=>({title:x.querySelector('[data-field="title"]').value,durationHours:Number(x.querySelector('[data-field="durationHours"]').value),price:Number(x.querySelector('[data-field="price"]').value),offeredItems:split(x.querySelector('[data-field="offeredItems"]').value),inclusions:split(x.querySelector('[data-field="inclusions"]').value),exclusions:split(x.querySelector('[data-field="exclusions"]').value),active:x.querySelector('[data-field="active"]').checked}))};try{const r=await api("/guides/me/profile",{method:"PUT",body:JSON.stringify(profile)});profile={...profile,...r.data,destinationIds:(r.data.destinationIds||[]).map(d=>typeof d==="string"?d:d._id)};drawGuide("Your local offering has been saved.","success")}catch(err){drawGuide(err.message,"error")}}; }
 } catch (e) { render(`<section class="wrap">${message(e.message,"error")}</section>`); } }

async function loadGuideRequests() {
  const host = document.querySelector("#guide-content");
  if (!host) return;
  try {
    const [{ data: requests }, { data: profile }] = await Promise.all([api("/guides/me/requests"), api("/guides/me/profile")]);
    host.insertAdjacentHTML("beforeend", `<section class="panel guide-contact-panel"><span class="eyebrow">TRIP CONTACT DETAILS</span><h2>How confirmed travelers can reach you</h2><p>These details remain private until you approve a trip. The in-app chat is available for every request.</p><form id="guide-contact-form" class="form-grid"><label>Phone / WhatsApp<input name="contactPhone" inputmode="tel" value="${esc(profile?.contactPhone || "")}" placeholder="+91 98765 43210"></label><label>Contact email<input name="contactEmail" type="email" value="${esc(profile?.contactEmail || "")}" placeholder="you@example.com"></label><div><button>Save contact details</button></div></form><div id="guide-contact-note"></div></section>`);
    host.querySelector("#guide-contact-form").onsubmit = async event => { event.preventDefault(); const note = host.querySelector("#guide-contact-note"); try { await api("/guides/me/contact", { method: "PUT", body: JSON.stringify(Object.fromEntries(new FormData(event.target))) }); note.innerHTML = message("Private trip contact details saved.", "success"); } catch (error) { note.innerHTML = message(error.message, "error"); } };
    host.insertAdjacentHTML("beforeend", `<section class="panel" style="margin-top:28px"><span class="eyebrow">TRAVELER REQUESTS</span><h2>Approve upcoming trips</h2><p>Review the traveler, dates, group size, and message before confirming your availability.</p><div class="list">${requests.length ? requests.map(request => `<article class="item"><div class="item-header"><div><b>${esc(request.destinationId?.name || "Destination")}</b><p>${esc(request.travelerId?.name || "Traveler")} · ${esc(request.travelerId?.email || "")}</p></div><span class="tag">${esc(request.status.replaceAll("_", " "))}</span></div><p>${new Date(request.startsAt).toLocaleDateString()} – ${new Date(request.endsAt).toLocaleDateString()} · ${request.guests} guest(s)</p><p>${esc(request.note || "No additional message from the traveler.")}</p>${request.status === "pending_guide_approval" ? `<div class="tags"><button class="request-decision" data-id="${request._id}" data-decision="approved">Approve trip</button><button class="button secondary request-decision" data-id="${request._id}" data-decision="declined">Decline</button></div>` : ""}</article>`).join("") : `<div class="empty">No traveler requests yet.</div>`}</div></section>`);
    host.querySelectorAll(".panel:last-child .item").forEach((card, index) => card.insertAdjacentHTML("beforeend", `<a class="text-link" href="#/trip?id=${requests[index]._id}">Open trip space & chat →</a>`));
    host.querySelectorAll(".request-decision").forEach(button => button.onclick = async () => { try { await api(`/guides/me/requests/${button.dataset.id}`, { method: "PATCH", body: JSON.stringify({ decision: button.dataset.decision }) }); location.hash = "#/account"; setTimeout(() => location.hash = "#/guide", 0); } catch (error) { alert(error.message); } });
  } catch (error) { host.insertAdjacentHTML("beforeend", message(error.message, "error")); }
}

function tripDate(value) { return new Date(value).toLocaleDateString("en-IN", { day:"numeric", month:"short", year:"numeric" }); }
function bookingCard(booking, isGuide = false) { const person = isGuide ? booking.travelerId?.name || "Traveler" : booking.guideId?.userId?.name || "Local guide"; return `<article class="trip-card"><div class="trip-card-top"><span class="status-pill ${esc(booking.status)}">${esc(booking.status.replaceAll("_", " "))}</span><span class="eyebrow">${esc(booking.destinationId?.state || "INDIA")}</span></div><h3>${esc(booking.destinationId?.name || "Your journey")}</h3><p class="trip-meta">${tripDate(booking.startsAt)} — ${tripDate(booking.endsAt)} · ${booking.guests} guest${booking.guests === 1 ? "" : "s"}</p><p class="trip-person">with <b>${esc(person)}</b></p><a class="button secondary" href="#/trip?id=${booking._id}">Open trip space <span>→</span></a></article>`; }
async function account() {
  render(`<section class="wrap"><div id="account-content" class="spinner">Preparing your travel space…</div></section>`);
  try {
    const [{ data: me }, { data: bookings }] = await Promise.all([api("/auth/me"), api("/bookings/mine")]); const user = me.user;
    document.querySelector("#account-content").innerHTML = `<div class="account-hero"><div><span class="eyebrow">YOUR TRAVEL SPACE</span><h1>Welcome back, ${esc(user.name)}.</h1><p>Your plans, local wisdom and conversations—held in one calm place.</p></div><button id="signout" class="button secondary">Sign out</button></div><div class="journey-layout"><section><div class="section-intro"><div><span class="eyebrow">YOUR ITINERARY</span><h2>Upcoming journeys</h2></div><a href="#/guides">Find a guide →</a></div><div class="trip-grid">${bookings.length ? bookings.map(booking => bookingCard(booking)).join("") : `<div class="empty">Your next story is still waiting. <a href="#/guides">Meet a local guide →</a></div>`}</div></section><aside class="memory-card"><span class="eyebrow">A THOUGHTFUL JOURNEY</span><h2>More than a booking.</h2><p>Open a trip to see your guide’s local offerings, approved contact details and private live chat.</p><a class="button light" href="#/planner">Start planning →</a></aside></div>`;
    if (user.roles.includes("admin")) document.querySelector(".memory-card").insertAdjacentHTML("beforeend", `<a class="button light" href="#/admin">Open admin portal →</a>`);
    document.querySelector("#signout").onclick = () => { clearToken(); setAccountLink(); location.hash = "#/"; };
  } catch { clearToken(); setAccountLink(); location.hash = "#/auth"; }
}
async function tripDetail() {
  if (!getToken()) return location.hash = "#/auth";
  const bookingId = new URLSearchParams(location.hash.split("?")[1] || "").get("id");
  if (!bookingId) return location.hash = "#/account";
  render(`<section class="wrap"><div class="spinner">Opening your trip space…</div></section>`);
  try {
    const [{ data: booking }, { data: me }, { data: messages }] = await Promise.all([api(`/bookings/${bookingId}`), api("/auth/me"), api(`/bookings/${bookingId}/messages`)]);
    const isGuide = booking.guideId?.userId?._id === me.user.id || booking.guideId?.userId?.id === me.user.id;
    const guide = booking.guideId || {}, guideName = guide.userId?.name || "Your local guide";
    const offeringMarkup = (guide.tripOfferings || []).length ? guide.tripOfferings.map(item => `<li><b>${esc(item.name)}</b>${item.description ? ` — ${esc(item.description)}` : ""}${item.included ? ` <span class="included">Included</span>` : item.extraCost ? ` <span class="extra">+ ${money(item.extraCost)}</span>` : ""}</li>`).join("") : `<li>Your guide will share tailored local recommendations in chat.</li>`;
    const contact = booking.guideContact ? `<div class="contact-card"><span class="eyebrow">CONFIRMED-TRIP CONTACT</span><h3>Reach ${esc(guideName)}</h3>${booking.guideContact.phone ? `<a href="tel:${esc(booking.guideContact.phone)}">☎ ${esc(booking.guideContact.phone)}</a>` : ""}${booking.guideContact.email ? `<a href="mailto:${esc(booking.guideContact.email)}">✉ ${esc(booking.guideContact.email)}</a>` : ""}${!booking.guideContact.phone && !booking.guideContact.email ? `<p>Contact details have not been added yet—use the secure chat below.</p>` : ""}</div>` : `<div class="contact-card muted-contact"><span class="eyebrow">CONTACT UNLOCKS ON APPROVAL</span><p>Your guide can be reached securely in chat while this request is being considered.</p></div>`;
    render(`<section class="trip-hero"><a class="back-link" href="#/account">← My journeys</a><div class="trip-title"><div><span class="eyebrow">${esc(booking.destinationId?.state || "INDIA")} · ${esc(booking.status.replaceAll("_", " "))}</span><h1>${esc(booking.destinationId?.name || "Your journey")}</h1><p>${tripDate(booking.startsAt)} — ${tripDate(booking.endsAt)} · ${booking.guests} guest${booking.guests === 1 ? "" : "s"}</p></div><div class="guide-avatar">${esc(guideName.slice(0, 1))}</div></div></section><section class="trip-layout"><div class="trip-main"><article class="detail-panel"><span class="eyebrow">YOUR LOCAL CONNECTION</span><h2>${esc(guideName)}</h2><p>${esc(guide.bio || "A verified local guide for this journey.")}</p><div class="tags">${(guide.languages || []).map(language => `<span class="tag">${esc(language)}</span>`).join("")}</div></article><article class="detail-panel"><span class="eyebrow">LOCAL GUIDE OFFERINGS</span><h2>Made for your kind of travel</h2><ul class="offering-list">${offeringMarkup}</ul></article><article class="chat-panel"><div class="chat-head"><div><span class="eyebrow">PRIVATE TRIP CHAT</span><h2>Plan together, in real time.</h2></div><span class="live-dot">Live</span></div><div class="messages" id="message-list"></div><form id="message-form" class="message-form"><input name="body" maxlength="2000" autocomplete="off" placeholder="Write a message to ${esc(isGuide ? booking.travelerId?.name || "the traveler" : guideName)}…"><button aria-label="Send message">Send ↑</button></form></article></div><aside class="trip-side">${contact}<div class="detail-panel"><span class="eyebrow">TRIP NOTE</span><p>${esc(booking.note || "No special requests were added to this trip.")}</p></div></aside></section>`);
    const list = document.querySelector("#message-list");
    const appendMessage = item => { if (list.querySelector(`[data-message-id="${item.id}"]`)) return; const mine = item.senderId === me.user.id || item.mine; list.insertAdjacentHTML("beforeend", `<div class="chat-bubble ${mine ? "mine" : ""}" data-message-id="${esc(item.id)}"><small>${mine ? "You" : esc(item.sender)}</small><p>${esc(item.body)}</p><time>${new Date(item.sentAt).toLocaleTimeString([], { hour:"2-digit", minute:"2-digit" })}</time></div>`); list.scrollTop = list.scrollHeight; };
    messages.forEach(appendMessage);
    document.querySelector("#message-form").onsubmit = async event => { event.preventDefault(); const input = event.target.elements.body; const body = input.value.trim(); if (!body) return; input.disabled = true; try { await api(`/bookings/${bookingId}/messages`, { method:"POST", body:JSON.stringify({ body }) }); input.value = ""; } catch (error) { alert(error.message); } finally { input.disabled = false; input.focus(); } };
    activeMessageStream = new EventSource(`/api/bookings/${bookingId}/messages/stream?token=${encodeURIComponent(getToken())}`); activeMessageStream.onmessage = event => appendMessage(JSON.parse(event.data));
  } catch (error) { render(`<section class="wrap">${message(error.message, "error")}<a class="button" href="#/account">Back to journeys</a></section>`); }
}

function contact() {
  render(`<section class="wrap contact-page"><div class="contact-intro"><span class="eyebrow">CONTACT YATRA VERSE</span><h1>Let’s make your next journey feel easy.</h1><p>Need help choosing a guide or planning a meaningful trip? Speak directly with our travel support team.</p></div><section class="direct-contact"><span class="eyebrow">DIRECT SUPPORT</span><h2>Talk to Shivam</h2><p><b>Shivam Pandey</b><br>Website owner & travel support</p><div class="contact-actions"><a class="contact-action call" href="tel:+917081127881" aria-label="Call Shivam Pandey on +91 70811 27881"><span>☎</span><div><small>CALL / WHATSAPP</small><b>+91 70811 27881</b></div></a><a class="contact-action email" href="mailto:pandeysp8080@gmail.com" aria-label="Email pandeysp8080@gmail.com"><span>✉</span><div><small>EMAIL SUPPORT</small><b>pandeysp8080@gmail.com</b></div></a></div><p class="notice">Tap the phone number to open your dialer, or the email card to open Gmail or your preferred email app.</p></section></section>`);
}
function chatMarkup(recipient) { return `<article class="chat-panel"><div class="chat-head"><div><span class="eyebrow">PRIVATE TRIP CHAT</span><h2>Plan together, in real time.</h2></div><span class="live-dot">Live</span></div><div class="messages" id="message-list"></div><form id="message-form" class="message-form"><input name="body" maxlength="2000" autocomplete="off" placeholder="Write a message to ${esc(recipient)}…"><button aria-label="Send message">Send ↑</button></form></article>`; }
function mountTripChat(bookingId, messages, userId) {
  const list = document.querySelector("#message-list");
  const appendMessage = item => { if (list.querySelector(`[data-message-id="${item.id}"]`)) return; const mine = item.senderId === userId || item.mine; list.insertAdjacentHTML("beforeend", `<div class="chat-bubble ${mine ? "mine" : ""}" data-message-id="${esc(item.id)}"><small>${mine ? "You" : esc(item.sender)}</small><p>${esc(item.body)}</p><time>${new Date(item.sentAt).toLocaleTimeString([], { hour:"2-digit", minute:"2-digit" })}</time></div>`); list.scrollTop = list.scrollHeight; };
  messages.forEach(appendMessage);
  document.querySelector("#message-form").onsubmit = async event => { event.preventDefault(); const input = event.target.elements.body, body = input.value.trim(); if (!body) return; input.disabled = true; try { await api(`/bookings/${bookingId}/messages`, { method:"POST", body:JSON.stringify({ body }) }); input.value = ""; } catch (error) { alert(error.message); } finally { input.disabled = false; input.focus(); } };
  activeMessageStream = new EventSource(`/api/bookings/${bookingId}/messages/stream?token=${encodeURIComponent(getToken())}`); activeMessageStream.onmessage = event => appendMessage(JSON.parse(event.data));
}
async function tripDetail() {
  if (!getToken()) return location.hash = "#/auth";
  const bookingId = new URLSearchParams(location.hash.split("?")[1] || "").get("id"); if (!bookingId) return location.hash = "#/account";
  render(`<section class="wrap"><div class="spinner">Opening your trip space…</div></section>`);
  try {
    const [{ data: booking }, { data: me }, { data: messages }] = await Promise.all([api(`/bookings/${bookingId}`), api("/auth/me"), api(`/bookings/${bookingId}/messages`)]);
    const isGuide = String(booking.guideId?.userId?._id || booking.guideId?.userId?.id || "") === String(me.user.id);
    const guide = booking.guideId || {}, guideName = guide.userId?.name || "Your local guide", traveler = booking.travelerId || {}, travelerName = traveler.name || "Your traveler";
    const back = isGuide ? "#/guide" : "#/account";
    if (isGuide) {
      const decision = booking.status === "pending_guide_approval" ? `<div class="guide-decisions"><button data-decision="approved">Approve trip</button><button class="button secondary" data-decision="declined">Decline request</button></div>` : `<p class="notice success">This trip is ${esc(booking.status.replaceAll("_", " "))}.</p>`;
      render(`<section class="trip-hero guide-trip-hero"><a class="back-link" href="${back}">← Guide portal</a><div class="trip-title"><div><span class="eyebrow">GUIDE TRIP BRIEF · ${esc(booking.status.replaceAll("_", " "))}</span><h1>${esc(booking.destinationId?.name || "Trip request")}</h1><p>${tripDate(booking.startsAt)} — ${tripDate(booking.endsAt)} · ${booking.guests} guest${booking.guests === 1 ? "" : "s"}</p></div><div class="guide-avatar traveler-avatar">${esc(travelerName.slice(0, 1))}</div></div></section><section class="trip-layout guide-trip-layout"><div class="trip-main"><article class="detail-panel traveler-brief"><span class="eyebrow">TRAVELER DETAILS</span><h2>${esc(travelerName)}</h2><p>This traveler is requesting your local expertise for the dates shown above.</p><div class="detail-contact"><span>EMAIL</span><a href="mailto:${esc(traveler.email || "")}">${esc(traveler.email || "Email not available")}</a></div><div class="detail-contact"><span>GROUP SIZE</span><b>${booking.guests} guest${booking.guests === 1 ? "" : "s"}</b></div></article><article class="detail-panel"><span class="eyebrow">THEIR TRIP REQUEST</span><h2>What they want from this journey</h2><p>${esc(booking.note || "No additional request was included. Start a chat to learn their interests and pace.")}</p></article>${chatMarkup(travelerName)}</div><aside class="trip-side"><div class="contact-card"><span class="eyebrow">GUIDE ACTIONS</span><h3>Confirm your availability</h3><p>Review the traveler’s dates and request before making a decision.</p>${decision}</div><div class="detail-panel"><span class="eyebrow">YOUR ROLE</span><p>Once approved, your saved phone and email will be shared with this traveler.</p></div></aside></section>`);
      document.querySelectorAll(".guide-decisions button").forEach(button => button.onclick = async () => { try { await api(`/guides/me/requests/${bookingId}`, { method:"PATCH", body:JSON.stringify({ decision:button.dataset.decision }) }); tripDetail(); } catch (error) { alert(error.message); } });
    } else {
      const offerings = (guide.tripOfferings || []).length ? guide.tripOfferings.map(item => `<li><b>${esc(item.name)}</b>${item.description ? ` — ${esc(item.description)}` : ""}${item.included ? ` <span class="included">Included</span>` : item.extraCost ? ` <span class="extra">+ ${money(item.extraCost)}</span>` : ""}</li>`).join("") : `<li>Your guide will share tailored local recommendations in chat.</li>`;
      const contactDetails = booking.guideContact ? `<div class="contact-card"><span class="eyebrow">CONFIRMED-TRIP CONTACT</span><h3>Reach ${esc(guideName)}</h3>${booking.guideContact.phone ? `<a href="tel:${esc(booking.guideContact.phone)}">☎ ${esc(booking.guideContact.phone)}</a>` : ""}${booking.guideContact.email ? `<a href="mailto:${esc(booking.guideContact.email)}">✉ ${esc(booking.guideContact.email)}</a>` : ""}${!booking.guideContact.phone && !booking.guideContact.email ? `<p>Use secure chat below while your guide adds their contact details.</p>` : ""}</div>` : `<div class="contact-card muted-contact"><span class="eyebrow">CONTACT UNLOCKS ON APPROVAL</span><p>Use the private chat while your guide considers this request.</p></div>`;
      render(`<section class="trip-hero"><a class="back-link" href="${back}">← My journeys</a><div class="trip-title"><div><span class="eyebrow">TRAVELER TRIP SPACE · ${esc(booking.status.replaceAll("_", " "))}</span><h1>${esc(booking.destinationId?.name || "Your journey")}</h1><p>${tripDate(booking.startsAt)} — ${tripDate(booking.endsAt)} · ${booking.guests} guest${booking.guests === 1 ? "" : "s"}</p></div><div class="guide-avatar">${esc(guideName.slice(0, 1))}</div></div></section><section class="trip-layout"><div class="trip-main"><article class="detail-panel"><span class="eyebrow">YOUR LOCAL GUIDE</span><h2>${esc(guideName)}</h2><p>${esc(guide.bio || "A verified local guide for this journey.")}</p><div class="tags">${(guide.languages || []).map(language => `<span class="tag">${esc(language)}</span>`).join("")}</div></article><article class="detail-panel"><span class="eyebrow">LOCAL GUIDE OFFERINGS</span><h2>Made for your kind of travel</h2><ul class="offering-list">${offerings}</ul></article>${chatMarkup(guideName)}</div><aside class="trip-side">${contactDetails}<div class="detail-panel"><span class="eyebrow">YOUR TRIP NOTE</span><p>${esc(booking.note || "No special requests were added to this trip.")}</p></div></aside></section>`);
    }
    mountTripChat(bookingId, messages, me.user.id);
  } catch (error) { render(`<section class="wrap">${message(error.message, "error")}<a class="button" href="#/account">Back to journeys</a></section>`); }
}

async function auth() {
  if (getToken()) return account();
  const showVerification = (email, role = "traveler", initial = "") => {
    let seconds = 60, timer;
    render(`<section class="wrap"><div class="panel otp-panel"><span class="eyebrow">YATRA VERSE · EMAIL SECURITY</span><h1>Verify your email</h1><p>We’ve sent a 6-digit verification code to <b>${esc(email)}</b>.</p><form id="otp-form"><label class="otp-label">Verification code<div class="otp-inputs">${Array.from({ length: 6 }, (_, index) => `<input class="otp-digit" inputmode="numeric" autocomplete="one-time-code" pattern="\\d*" maxlength="1" aria-label="Digit ${index + 1}">`).join("")}</div></label><button id="verify-otp">Verify Email</button></form><div id="otp-message">${message(initial)}</div><p class="otp-resend">Didn’t receive it? <button id="resend-otp" class="text-button" disabled>Resend OTP in ${seconds}s</button></p><button id="back-to-auth" class="button secondary">Use a different email</button></div></section>`);
    const digits = [...document.querySelectorAll(".otp-digit")], out = document.querySelector("#otp-message"), resend = document.querySelector("#resend-otp");
    const setCooldown = () => { resend.disabled = true; resend.textContent = `Resend OTP in ${seconds}s`; clearInterval(timer); timer = setInterval(() => { seconds -= 1; resend.textContent = seconds ? `Resend OTP in ${seconds}s` : "Resend OTP"; if (!seconds) { clearInterval(timer); resend.disabled = false; } }, 1000); };
    digits.forEach((input, index) => { input.oninput = () => { input.value = input.value.replace(/\D/g, "").slice(-1); if (input.value && digits[index + 1]) digits[index + 1].focus(); }; input.onkeydown = event => { if (event.key === "Backspace" && !input.value && digits[index - 1]) digits[index - 1].focus(); }; input.onpaste = event => { const code = (event.clipboardData.getData("text").match(/\d/g) || []).join("").slice(0, 6); if (!code) return; event.preventDefault(); code.split("").forEach((digit, position) => { if (digits[position]) digits[position].value = digit; }); digits[Math.min(code.length, 6) - 1].focus(); }; });
    digits[0].focus(); setCooldown();
    document.querySelector("#otp-form").onsubmit = async event => { event.preventDefault(); const otp = digits.map(input => input.value).join(""); const button = document.querySelector("#verify-otp"); if (!/^\d{6}$/.test(otp)) { out.innerHTML = message("Enter all six digits from your email.", "error"); return; } button.disabled = true; button.textContent = "Verifying…"; try { const result = await api("/auth/verify-email", { method:"POST", body:JSON.stringify({ email, otp }) }); saveToken(result.data.accessToken); setAccountLink(); out.innerHTML = message("Email verified. Opening your account…", "success"); setTimeout(() => location.hash = result.data.user.roles.includes("guide") ? "#/guide" : "#/account", 450); } catch (error) { out.innerHTML = message(error.message, "error"); } finally { button.disabled = false; button.textContent = "Verify Email"; } };
    resend.onclick = async () => { resend.disabled = true; try { await api("/auth/resend-verification", { method:"POST", body:JSON.stringify({ email }) }); seconds = 60; setCooldown(); out.innerHTML = message("A new verification code has been sent.", "success"); digits.forEach(input => input.value = ""); digits[0].focus(); } catch (error) { out.innerHTML = message(error.message, "error"); seconds = 10; setCooldown(); } };
    document.querySelector("#back-to-auth").onclick = () => { clearInterval(timer); auth(); };
  };
  render(`<section class="wrap"><div class="panel auth-panel"><span class="eyebrow">YATRA VERSE</span><h1 id="auth-title">Welcome back.</h1><form id="auth-form"><div id="register-fields" class="hidden"><label>Name<input name="name" minlength="2"></label><label>I’m joining as<select name="role"><option value="traveler">Traveler</option><option value="guide">Local guide</option></select></label></div><label>Email<input name="email" type="email" required></label><label>Password<input name="password" type="password" minlength="8" required></label><button id="auth-submit">Sign in</button></form><div id="auth-message"></div><button class="button secondary" id="mode-toggle">Need an account? Register</button></div></section>`);
  let mode = "login";
  document.querySelector("#mode-toggle").onclick = () => { mode = mode === "login" ? "register" : "login"; document.querySelector("#register-fields").classList.toggle("hidden", mode === "login"); document.querySelector("#auth-title").textContent = mode === "login" ? "Welcome back." : "Begin your journey."; document.querySelector("#auth-submit").textContent = mode === "login" ? "Sign in" : "Create account"; document.querySelector("#mode-toggle").textContent = mode === "login" ? "Need an account? Register" : "Already have an account? Sign in"; };
  document.querySelector("#auth-form").onsubmit = async event => { event.preventDefault(); const out = document.querySelector("#auth-message"), form = Object.fromEntries(new FormData(event.target)), button = document.querySelector("#auth-submit"); button.disabled = true; try { const result = await api(`/auth/${mode}`, { method:"POST", body:JSON.stringify(form) }); if (mode === "register") return showVerification(result.data.email, result.data.role); saveToken(result.data.accessToken); setAccountLink(); location.hash = result.data.user.roles.includes("guide") ? "#/guide" : "#/account"; } catch (error) { out.innerHTML = message(error.message, "error"); if (mode === "login" && /verify your email/i.test(error.message)) { out.insertAdjacentHTML("beforeend", `<button class="text-button" id="continue-verification">Verify ${esc(form.email)}</button>`); document.querySelector("#continue-verification").onclick = () => showVerification(form.email); } } finally { button.disabled = false; } };
}

function outlookQuery(destinationId, date) { return `destination=${encodeURIComponent(destinationId)}&date=${encodeURIComponent(date)}`; }
function outlookCard(type, title, status, body, destinationId, date) { return `<a class="metric outlook-card" href="#/outlook/${type}?${outlookQuery(destinationId, date)}"><span class="status ${esc(status)}">${esc(status)}</span><h3>${esc(title)}</h3><p>${esc(body)}</p><b class="open-outlook">Open detailed outlook →</b></a>`; }
async function plannerLive() {
  render(`<section class="wrap"><div class="page-head"><div><span class="eyebrow">DATE-AWARE TRAVEL INTELLIGENCE</span><h1>Plan with context.</h1><p>Choose a destination and date for weather, live city traffic and active route incidents.</p></div></div><section class="panel"><form id="advisory-form" class="form-grid"><label>Destination<select name="destination" required><option value="">Loading destinations…</option></select></label><label>Travel date<input name="date" type="date" required></label><div><button>Check travel conditions</button></div></form><div class="notice">Each result card opens a detailed page. Live traffic and incident data require the server-side TomTom API key.</div></section><section id="advisory-result" class="panel hidden"></section></section>`);
  const dateInput = document.querySelector('[name="date"]'), tomorrow = new Date(); tomorrow.setDate(tomorrow.getDate() + 1); dateInput.value = tomorrow.toISOString().slice(0, 10); dateInput.min = new Date().toISOString().slice(0, 10);
  try { const { data } = await api("/destinations"); const select = document.querySelector('[name="destination"]'); select.innerHTML = `<option value="">Choose a destination</option>${data.map(item => `<option value="${item._id}">${esc(item.name)} · ${esc(item.state)}</option>`).join("")}`; const preferred = new URLSearchParams(location.hash.split("?")[1] || "").get("destination"); if (preferred) select.value = preferred; } catch (error) { document.querySelector("#advisory-form").insertAdjacentHTML("afterend", message(error.message, "error")); }
  document.querySelector("#advisory-form").onsubmit = async event => { event.preventDefault(); const form = new FormData(event.target), destinationId = form.get("destination"), date = form.get("date"), output = document.querySelector("#advisory-result"); output.classList.remove("hidden"); output.innerHTML = `<p class="spinner">Loading your travel outlook…</p>`; try { const { data } = await api(`/travel-advisory/${destinationId}?date=${date}`); const temperature = data.weather.temperature ? `${data.weather.temperature.min}–${data.weather.temperature.max}${data.weather.temperature.unit}` : "Weather data is not available."; const trafficText = data.traffic.currentSpeed != null ? `${data.traffic.summary} Free-flow speed: ${data.traffic.freeFlowSpeed ?? "—"} km/h.` : data.traffic.summary; output.innerHTML = `<span class="eyebrow">${esc(data.destination)} · ${esc(data.date)}</span><h2>Your travel outlook</h2><div class="advisory">${outlookCard("weather", data.weather.summary, data.weather.status, temperature, destinationId, date)}${outlookCard("traffic", "City traffic", data.traffic.status, trafficText, destinationId, date)}${outlookCard("routes", "Route incidents", data.route.status, data.route.summary, destinationId, date)}</div><h3>Weather planning notes</h3><div>${data.hazards.map(hazard => `<div class="hazard"><b>${esc(hazard.title)} <span class="tag">${esc(hazard.level)}</span></b>${esc(hazard.detail)}</div>`).join("")}</div>`; } catch (error) { output.innerHTML = message(error.message, "error"); } };
}
function mountLiveTrafficMap(element) {
  const latitude = Number(element.dataset.latitude), longitude = Number(element.dataset.longitude);
  if (!window.L || !Number.isFinite(latitude) || !Number.isFinite(longitude)) { element.innerHTML = `<p class="map-error">Map could not be loaded.</p>`; return; }
  const map = window.L.map(element, { scrollWheelZoom: false }).setView([latitude, longitude], 12);
  window.L.tileLayer("https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png", { maxZoom: 19, attribution: "© OpenStreetMap contributors" }).addTo(map);
  const trafficLayer = window.L.tileLayer("/api/traffic-tiles/{z}/{x}/{y}.png", { maxZoom: 22, opacity: .9, attribution: "Traffic © TomTom" });
  trafficLayer.on("tileerror", () => { const notice = element.parentElement.querySelector(".traffic-layer-note"); if (notice) notice.hidden = false; });
  trafficLayer.addTo(map);
  window.L.circleMarker([latitude, longitude], { radius: 7, color: "#47236c", fillColor: "#ffffff", fillOpacity: 1, weight: 3 }).addTo(map).bindTooltip(element.dataset.destination || "Selected destination");
}
async function outlookDetails(kind) {
  const params = new URLSearchParams(location.hash.split("?")[1] || ""), destinationId = params.get("destination"), date = params.get("date");
  if (!destinationId || !date) return location.hash = "#/planner";
  render(`<section class="wrap"><div class="spinner">Loading live outlook…</div></section>`);
  try {
    const [{ data: advisory }, { data: destinations }] = await Promise.all([api(`/travel-advisory/${destinationId}?date=${date}`), api("/destinations")]);
    const destination = destinations.find(item => item._id === destinationId), [longitude, latitude] = destination?.coordinates?.coordinates || [];
    const map = typeof latitude === "number" && typeof longitude === "number" ? `<iframe class="city-map" title="Map of ${esc(advisory.destination)}" src="https://www.openstreetmap.org/export/embed.html?bbox=${longitude - .06}%2C${latitude - .04}%2C${longitude + .06}%2C${latitude + .04}&layer=mapnik&marker=${latitude}%2C${longitude}"></iframe><a class="map-link" target="_blank" rel="noreferrer" href="https://www.openstreetmap.org/?mlat=${latitude}&mlon=${longitude}#map=12/${latitude}/${longitude}">Open larger map ↗</a>` : "";
    const back = `<a class="back-link" href="#/planner?destination=${encodeURIComponent(destinationId)}">← Travel outlook</a>`;
    if (kind === "weather") return render(`<section class="wrap outlook-page">${back}<span class="eyebrow">WEATHER OUTLOOK · ${esc(advisory.date)}</span><h1>${esc(advisory.destination)}</h1><article class="outlook-detail"><span class="status ${esc(advisory.weather.status)}">${esc(advisory.weather.status)}</span><h2>${esc(advisory.weather.summary)}</h2><p class="outlook-stat">${advisory.weather.temperature ? `${advisory.weather.temperature.min}–${advisory.weather.temperature.max}${advisory.weather.temperature.unit}` : "—"}</p><p>${advisory.weather.precipitation ? `${advisory.weather.precipitation.chance}% chance of precipitation · ${advisory.weather.precipitation.amount}${advisory.weather.precipitation.unit}` : "No precipitation estimate available."}</p><small>Source: ${esc(advisory.weather.source || "Unavailable")}</small></article><h2>Planning notes</h2>${advisory.hazards.map(hazard => `<div class="hazard"><b>${esc(hazard.title)}</b>${esc(hazard.detail)}</div>`).join("")}</section>`);
    if (kind === "traffic") return render(`<section class="wrap outlook-page">${back}<span class="eyebrow">LIVE CITY TRAFFIC · ${esc(advisory.destination)}</span><h1>City traffic outlook</h1><div class="outlook-map-layout"><div><article class="outlook-detail"><span class="status ${esc(advisory.traffic.status)}">${esc(advisory.traffic.status)}</span><h2>${esc(advisory.traffic.summary)}</h2><p class="outlook-stat">${advisory.traffic.currentSpeed != null ? `${advisory.traffic.currentSpeed} km/h` : "—"}</p><p>${advisory.traffic.freeFlowSpeed != null ? `Normal flow on this segment is approximately ${advisory.traffic.freeFlowSpeed} km/h.` : "Add TOMTOM_TRAFFIC_API_KEY in backend/.env to activate live city traffic."}</p><small>Source: ${esc(advisory.traffic.source || "TomTom configuration required")}</small></article></div><div>${map}</div></div></section>`);
    const incidents = advisory.route.diversions?.length ? `<ul class="incident-list">${advisory.route.diversions.map(item => `<li>${esc(item)}</li>`).join("")}</ul>` : `<p>No active incidents are currently reported near this destination.</p>`;
    render(`<section class="wrap outlook-page">${back}<span class="eyebrow">LIVE ROUTE INCIDENTS · ${esc(advisory.destination)}</span><h1>Route outlook</h1><div class="outlook-map-layout"><article class="outlook-detail"><span class="status ${esc(advisory.route.status)}">${esc(advisory.route.status)}</span><h2>${esc(advisory.route.summary)}</h2>${incidents}<small>Source: ${esc(advisory.route.source || "TomTom configuration required")}</small></article><div>${map}</div></div></section>`);
  } catch (error) { render(`<section class="wrap">${message(error.message, "error")}<a class="button" href="#/planner">Back to planner</a></section>`); }
}
const weatherOutlook = () => outlookDetails("weather"), trafficOutlook = () => outlookDetails("traffic"), routesOutlook = () => outlookDetails("routes");
const routes = { "":home, "/":home, "/destinations":destinations, "/guides":guides, "/planner":plannerLive, "/outlook/weather":weatherOutlook, "/outlook/traffic":trafficOutlook, "/outlook/routes":routesOutlook, "/request":tripRequest, "/auth":auth, "/account":account, "/trip":tripDetail, "/guide":guidePortal, "/admin":adminPortal, "/contact":contact };
async function router() { try { setAccountLink(); const path = location.hash.slice(1).split("?")[0] || "/"; await (routes[path] || home)(); if (path === "/guide") await loadGuideRequests(); } catch (error) { console.error("Unable to render page:", error); app.innerHTML = `<section class="wrap"><div class="notice error"><b>We could not load this page.</b><br>${esc(error?.message || "Please refresh and try again.")}</div><a class="button" href="#/">Return home</a></section>`; } }
window.addEventListener("hashchange", router); router();
